// Initialize sum to 0
@R2
M=0

(LOOP)
	// If R1 == 0, we're done
	@R1
	D=M
	@END
	D;JEQ

	// R2 = R2 + R0
	@R0
	D=M
	@R2
	M=D+M

	// R1 = R1 - 1
	@R1
	M=M-1

	@LOOP
	0;JMP

(END)
	@END
	0;JMP

// Infinite loop: poll KBD, then repaint the entire screen.

(MAIN)
	// Decide the fill color based on keyboard input
	@KBD
	D=M
	@WHITE
	D;JEQ          // no key pressed -> white

	// Key pressed -> black
	@color
	M=-1
	@FILL
	0;JMP

(WHITE)
	@color
	M=0

(FILL)
	// addr = SCREEN, count = 8192
	@SCREEN
	D=A
	@addr
	M=D
	@8192
	D=A
	@count
	M=D

(LOOP)
	// If count == 0, repaint is done; poll the keyboard again
	@count
	D=M
	@MAIN
	D;JEQ

	// RAM[addr] = color
	@color
	D=M
	@addr
	A=M
	M=D

	// addr++, count--
	@addr
	M=M+1
	@count
	M=M-1

	@LOOP
	0;JMP

