import sys

PREDEF = {'SP':0,'LCL':1,'ARG':2,'THIS':3,'THAT':4,
          **{f'R{i}':i for i in range(16)},
          'SCREEN':16384,'KBD':24576}

def assemble(path):
    lines = []
    for raw in open(path):
        s = raw.split('//')[0].strip()
        if s:
            lines.append(s)
    sym = dict(PREDEF)
    rom = []
    for s in lines:
        if s.startswith('('):
            sym[s[1:-1]] = len(rom)
        else:
            rom.append(s)
    nxt = 16
    out = []
    for s in rom:
        if s.startswith('@'):
            v = s[1:]
            if v.isdigit():
                a = int(v)
            else:
                if v not in sym:
                    sym[v] = nxt; nxt += 1
                a = sym[v]
            out.append(('A', a))
        else:
            dest, rest, jump = '', s, ''
            if '=' in rest:
                dest, rest = rest.split('=')
            if ';' in rest:
                rest, jump = rest.split(';')
            out.append(('C', dest.strip(), rest.strip(), jump.strip()))
    return out

def compute(comp, D, A, M):
    vals = {'0':0,'1':1,'-1':-1,
            'D':D,'A':A,'M':M,
            '!D':~D & 0xFFFF,'!A':~A & 0xFFFF,'!M':~M & 0xFFFF,
            '-D':(-D)&0xFFFF,'-A':(-A)&0xFFFF,'-M':(-M)&0xFFFF,
            'D+1':(D+1)&0xFFFF,'A+1':(A+1)&0xFFFF,'M+1':(M+1)&0xFFFF,
            'D-1':(D-1)&0xFFFF,'A-1':(A-1)&0xFFFF,'M-1':(M-1)&0xFFFF,
            'D+A':(D+A)&0xFFFF,'D+M':(D+M)&0xFFFF,
            'D-A':(D-A)&0xFFFF,'D-M':(D-M)&0xFFFF,
            'A-D':(A-D)&0xFFFF,'M-D':(M-D)&0xFFFF,
            'D&A':D&A,'D&M':D&M,'D|A':D|A,'D|M':D|M}
    if comp not in vals:
        raise ValueError('bad comp: '+comp)
    return vals[comp]

def s16(x):
    return x - 0x10000 if x & 0x8000 else x

def run(path, ram_init=None, kbd=None, max_steps=2_000_000, stop_pc=None):
    code = assemble(path)
    RAM = [0]*24577
    if ram_init:
        for k,v in ram_init.items(): RAM[k]=v & 0xFFFF
    D=A=0; pc=0; steps=0
    while steps < max_steps:
        steps += 1
        if kbd is not None:
            RAM[24576] = kbd
        ins = code[pc]
        if ins[0]=='A':
            A = ins[1]; pc += 1
        else:
            _, dest, comp, jump = ins
            val = compute(comp, D, A, RAM[A])
            if 'A' in dest: A = val
            if 'D' in dest: D = val
            if 'M' in dest: RAM[A] = val
            j = s16(val)
            take = {'':0,'JGT':j>0,'JEQ':j==0,'JGE':j>=0,
                    'JLT':j<0,'JNE':j!=0,'JLE':j<=0,'JMP':1}[jump]
            if take:
                pc = A
                if pc == stop_pc:
                    break
                if steps > 40 and pc == prev_pc and jump=='JMP' and not dest and comp=='0':
                    # tight 0;JMP self loop = halt
                    break
            else:
                pc += 1
        prev_pc = pc
    return RAM, steps

def test_mult():
    for a,b in [(0,0),(1,0),(0,4),(2,4),(3,3),(7,3),(6,7),(4,9),(1,1),(15,15)]:
        RAM,_ = run('/workspace/projects/04/mult/Mult.asm', {0:a,1:b})
        assert RAM[2]==a*b, (a,b,RAM[2])
    print('Mult OK')

def test_add():
    RAM,_ = run('/workspace/projects/06/add/Add.asm')
    assert RAM[0]==5, RAM[0]
    print('Add OK')

def test_max(p):
    for a,b in [(0,0),(1,0),(0,4),(2,4),(3,3),(-1,-3),(-3,2),(100,200)]:
        RAM,_ = run(p, {0:a&0xFFFF,1:b&0xFFFF})
        assert s16(RAM[2])==max(a,b), (p,a,b,s16(RAM[2]))
    print(p, 'OK')

def test_rect(p):
    for h in [0,1,4,10]:
        RAM,_ = run(p, {0:h})
        for row in range(h):
            assert RAM[16384+32*row]==0xFFFF, (p,h,row)
        # rows past h should be untouched (0)
        assert RAM[16384+32*h]==0, (p,h)
    print(p, 'OK')

def test_fill():
    # keyboard pressed -> whole screen -1; released -> whole screen 0
    RAM,_ = run('/workspace/projects/04/fill/Fill.asm', kbd=65, max_steps=200_000)
    assert all(RAM[16384+i]==0xFFFF for i in range(8192)), 'fill black failed'
    # now clear: prefill screen black, no key
    init = {16384+i:0xFFFF for i in range(8192)}
    RAM,_ = run('/workspace/projects/04/fill/Fill.asm', ram_init=init, kbd=0, max_steps=200_000)
    assert all(RAM[16384+i]==0 for i in range(8192)), 'fill white failed'
    print('Fill OK')

test_mult(); test_add()
test_max('/workspace/projects/06/max/Max.asm')
test_max('/workspace/projects/06/max/MaxL.asm')
test_rect('/workspace/projects/06/rect/Rect.asm')
test_rect('/workspace/projects/06/rect/RectL.asm')
test_fill()
print('ALL PASS')

